%% ofk 1
erd
title: TokenBurnTrack — Data Model
harness [orange] { id text pk   display_name text   enabled int   roots_json text }
source_file [gray] { id int pk   harness_id text fk   path text   cursor_json text   last_read text   missing int }
project [teal] { id int pk   path text unique   name text }
session [blue] { id int pk   harness_id text fk   ext_id text   project_id int fk   resumed_from_session_id int fk   started_at text   ended_at text   active_seconds int   cost_micros int }
usage_event [violet] { id int pk   harness_id text   dedup_key text unique   session_id int fk   ts text   model text   input_tokens int   output_tokens int   cache_write_5m_tokens int   cache_write_1h_tokens int   cache_read_tokens int   cost_micros int   reported_cost_micros int   price_id int fk   source_file_id int fk }
message [pink] { id int pk   session_id int fk   ts text   role text   tool_name text   preview text   usage_event_id int fk }
hourly_usage [green] { hour text pk   harness_id text pk   model text pk   project_id int pk   input_tokens int   output_tokens int   cost_micros int }
model_price [yellow] { id int pk   provider text   model_pattern text   effective_from text   effective_to text   input_per_mtok text   output_per_mtok text   cache_read_per_mtok text   source text }
ingest_run [gray] { id int pk   trigger text   started_at text   finished_at text   events_new int   warnings_json text }
harness ||--o{ source_file : has
harness ||--o{ session : owns
project |o--o{ session : groups
session |o--o{ session : resumed_from
session ||--o{ usage_event : contains
session ||--o{ message : contains
source_file |o--o{ usage_event : origin
model_price |o--o{ usage_event : prices
usage_event |o--o{ message : produced
